 (function(){
function run(){
 // 1. time[datetime] 처리
 document.querySelectorAll('time[datetime],.nyt-post-date time').forEach(function(el){
 var m=(el.getAttribute('datetime')||'').match(/(\d{4})-(\d{2})-(\d{2})/);
 if(m){el.textContent=parseInt(m[2])+'월 '+parseInt(m[3])+'일';}
 });
 // 2. 카드 날짜 span 처리
 document.querySelectorAll('.kth-meta span:not(.kth-meta-author):not(.kth-meta-sep):not(.kth-badge)').forEach(function(el){
 var t=(el.textContent||'').trim();
 // "4월 3, 2026" 형태
 if(/^\d{1,2}월\s*\d{1,2}[,，]\s*\d{4}$/.test(t)){
 var p=t.match(/^(\d{1,2})월\s*(\d{1,2})/);
 if(p){el.textContent=p[1]+'월 '+p[2]+'일';}
 return;
 }
 // "4월 3" 형태 (월일만)
 if(/^\d{1,2}월\s*\d{1,2}$/.test(t)){
 var p=t.match(/^(\d{1,2})월\s*(\d{1,2})/);
 if(p){el.textContent=p[1]+'월 '+p[2]+'일';}
 }
 });
 // 3. 읽기시간
 document.querySelectorAll('.nyt-post-read,.kth-post-read').forEach(function(el){
 var m=(el.textContent||'').match(/(\d+)/);
 if(m){el.textContent=m[1]+'분 읽기';}
 });
 // 4. 테이블
 document.querySelectorAll('table').forEach(function(t){t.style.setProperty('background','#f0f4ff','important');});
 document.querySelectorAll('td').forEach(function(c){c.style.setProperty('background','#eef2ff','important');c.style.setProperty('color','#1a2340','important');});
 document.querySelectorAll('th').forEach(function(c){c.style.setProperty('background','#dce6ff','important');c.style.setProperty('color','#0d1526','important');});
}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',run);}else{run();}
window.addEventListener('load',run);
})();
